#include <string.h>
int wordBreak(char*s,char*words[],int wc){int n=strlen(s),dp[n+1];dp[0]=1;
for(int i=1;i<=n;i++){dp[i]=0;for(int j=0;j<wc&&!dp[i];j++){int l=strlen(words[j]);if(i>=l&&dp[i-l]&&!strncmp(s+i-l,words[j],l))dp[i]=1;}}return dp[n];}

